 if($action==='add_to_exam'){$bankId=(int)($_POST['bank_id']??0);$examStmt=db()->prepare('SELECT * FROM exams WHERE id=? AND (created_by=? OR ?=1)');$examStmt->execute([$examId,$uid,$isAdmin?1:0]);$exam=$examStmt->fetch();if(!$exam){http_response_code(403);exit('آزمون مجاز نیست.');}$q=db()->prepare('SELECT qb.* FROM question_bank qb JOIN subjects sb ON sb.id=qb.subject_id WHERE qb.id=? AND qb.is_active=1 AND (qb.owner_id=? OR sb.created_by=? OR ?=1)');$q->execute([$bankId,$uid,$uid,$isAdmin?1:0]);$bank=$q->fetch();if(!$bank){flash('error','پرسش بانک پیدا نشد.');redirect('teacher/question_bank.php?exam_id='.$examId);}$o=db()->prepare('SELECT * FROM question_bank_options WHERE bank_question_id=? ORDER BY sort_order,id');$o->execute([$bankId]);$order=db()->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM questions WHERE exam_id=?');$order->execute([$examId]);$insert=db()->prepare('INSERT INTO questions(exam_id,question_text,image_path,question_type,score,sort_order,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?)');$insert->execute([$examId,$bank['question_text'],$bank['image_path']??null,$bank['question_type'],$bank['score'],(int)$order->fetchColumn(),$bank['reference_answer'],$bank['rubric']]);$newQ=(int)db()->lastInsertId();$oi=db()->prepare('INSERT INTO question_options(question_id,option_text,image_path,option_key,is_correct,sort_order) VALUES(?,?,?,?,?,?)');foreach($o as $option)$oi->execute([$newQ,$option['option_text'],$option['image_path']??null,$option['option_key'],$option['is_correct'],$option['sort_order']]);flash('success','پرسش به آزمون اضافه شد.');redirect('teacher/question_bank.php?exam_id='.$examId);}
 if($action==='add_selected_to_exam'){$selected=$_POST['selected']??[];$selectedIds=[];foreach((array)$selected as $id){$n=(int)$id;if($n>0)$selectedIds[]=$n;}if(!$selectedIds){flash('error','هیچ سؤالی انتخاب نشده است.');redirect('teacher/question_bank.php?exam_id='.$examId);} $examStmt=db()->prepare('SELECT * FROM exams WHERE id=? AND (created_by=? OR ?=1)');$examStmt->execute([$examId,$uid,$isAdmin?1:0]);$exam=$examStmt->fetch();if(!$exam){http_response_code(403);exit('آزمون مجاز نیست.');}$ids=implode(',', array_fill(0,count($selectedIds),'?')); $bankStmt=db()->prepare('SELECT qb.* FROM question_bank qb JOIN subjects sb ON sb.id=qb.subject_id WHERE qb.id IN ('.$ids.') AND qb.is_active=1 AND (qb.owner_id=? OR sb.created_by=? OR ?=1)');$params=array_merge($selectedIds,[$uid,$uid,$isAdmin?1:0]);$bankStmt->execute($params);$banks=$bankStmt->fetchAll();if(!$banks){flash('error','سؤال‌های انتخاب‌شده پیدا نشدند.');redirect('teacher/question_bank.php?exam_id='.$examId);} $orderStmt=db()->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM questions WHERE exam_id=?');$orderStmt->execute([$examId]);$nextOrder=(int)$orderStmt->fetchColumn();$pdo=db();$pdo->beginTransaction();try{$insertQ=$pdo->prepare('INSERT INTO questions(exam_id,question_text,image_path,question_type,score,sort_order,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?)');$insertO=$pdo->prepare('INSERT INTO question_options(question_id,option_text,image_path,option_key,is_correct,sort_order) VALUES(?,?,?,?,?,?)');foreach($banks as $bank){$ops=db()->prepare('SELECT * FROM question_bank_options WHERE bank_question_id=? ORDER BY sort_order,id');$ops->execute([$bank['id']]);$insertQ->execute([$examId,$bank['question_text'],$bank['image_path']??null,$bank['question_type'],$bank['score'],$nextOrder++,$bank['reference_answer'],$bank['rubric']]);$newQ=(int)$pdo->lastInsertId();foreach($ops as $option)$insertO->execute([$newQ,$option['option_text'],$option['image_path']??null,$option['option_key'],$option['is_correct'],$option['sort_order']]);}$pdo->commit();flash('success',count($banks).' سؤال به آزمون اضافه شد.');}catch(Throwable $e){$pdo->rollBack();flash('error','افزودن چند سؤال انجام نشد: '.$e->getMessage());}redirect('teacher/question_bank.php?exam_id='.$examId);}
