?><div class="card class-toolbar"><div><span class="eyebrow">مدیریت محتوای آموزشی</span><h1>بانک سؤال</h1><p class="muted">پرسش‌ها را دستی یا با فایل Word ذخیره و در آزمون‌های مختلف استفاده کنید.</p></div><form class="search-form" method="get"><?php if($examId):?><input type="hidden" name="exam_id" value="<?=$examId?>"><?php endif;?><input name="q" value="<?=e($search)?>" placeholder="جست‌وجوی متن سؤال یا درس"><select name="filter_chapter" aria-label="فیلتر پودمان"><option value="">همهٔ پودمان‌ها</option><?php foreach($availableChapters as $chapter):?><option value="<?=e($chapter)?>" <?=($filterChapter===$chapter)?'selected':''?>><?=e($chapter)?></option><?php endforeach;?></select><button class="btn btn-primary">جست‌وجو</button></form></div><?php if($errors):?><div class="alert danger"><strong>خطاهای واردسازی:</strong><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><?php if($examId):?><div class="alert success">آزمون مقصد: شمارهٔ <?=e((string)$examId)?> — از فهرست زیر روی «افزودن به آزمون» بزنید.</div><?php endif;?><?php if($editBank):?><div class="card"><h2>ویرایش سؤال بانک</h2><form method="post" enctype="multipart/form-data" class="grid grid-2"><?=csrf_field()?><input type="hidden" name="action" value="update_bank_question"><input type="hidden" name="id" value="<?=$editBank['id']?>"><?php if($examId):?><input type="hidden" name="exam_id" value="<?=$examId?>"><?php endif;?><div class="form-group"><label>درس</label><select name="subject_id" required><option value="">انتخاب کنید</option><?php foreach($subjects as $subject):?><option value="<?=$subject['id']?>" <?=($editBank['subject_id']===$subject['id'])?'selected':''?>><?=e($subject['title'].(!empty($subject['grade_level'])?' - '.$subject['grade_level']:'').(!empty($subject['field_name'])?' - '.$subject['field_name']:''))?></option><?php endforeach;?></select></div><div class="form-group"><label>فصل / مبحث</label><input name="chapter" maxlength="150" value